{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.omnichannel_sla_performance as WITH unicom AS ( SELECT awb, MARKETPLACE, marketplace_mapped, shippingpackagecode, order_id, order_name, SELLING_PRICE, saleorderitemcode, sku, order_status, order_date, order_timestamp, SHIPPING_LAST_UPDATE_TIMESTAMP, shipping_courier, warehouse_name, shipping_status, ON_HOLD, CASE WHEN SALE_ORDER_ITEM_STATUS = \'PICKING_FOR_INVOICING\' THEN shippingpackagestatus ELSE SALE_ORDER_ITEM_STATUS END AS UC_STATUS, dispatched_timestamp AS \"UC_Dispatched\", dispatch_date, delivered_date, item_details, address_line_1, uc_created, CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 17 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'1050 minute\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 17 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'1050 minute\' ELSE fulfillment_tat END AS TAT, category, SHIPPING_PACKAGE_TYPE, REVERSE_PICKUP_CODE, REVERSE_PICKUP_CREATED, NOTIFICATION_EMAIL, NOTIFICATION_MOBILE, CUSTOMIZATION, COD, SHIPPING_ID, CANCELLATION_REASON, SHIPPING_ARRANGED_BY, PACKAGE_LENGTH, PACKAGE_WIDTH, PACKAGE_HEIGHT, RETURN_DATE, RETURN_REASON, RETURN_REMARKS, ITEM_CODE, weight, SKU_NAME, SHIPPING_COURIER_STATUS, SHIPPING_TRACKING_STATUS, packed_time, PACKING_USER, ITEM_FINAL_STATUS, pincode FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 ), forward AS ( SELECT \"Shipping Package Code\", created_timestamp, picking_timestamp, picked_timestamp, packed_timestamp, rts_timestamp, manifested_timestamp, dispatched_timestamp AS dispatched_timestamp1, shipped_timestamp, delivered_timestamp, cancelled_timestamp, \"created&dispatch\", \"pick&dispatch\", \"pack&dispatch\", LATEST_STATUS, LAST_UPDATED FROM snitch_db.maplemonk.forward_timestamps ), clickpost AS ( SELECT awb, \"Order Date\" AS CP_orderplaced, \"Pickup Date\", \"Delivery Date\" AS CP_Delivery, \"Clickpost Unified Status\" as CP_STATUS FROM snitch_db.maplemonk.snitch_clickpost_track_order_dashboard_report ), sr AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_SR ), wh AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH ), wh2 AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH2 ), emiza AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_EMIZA ), marketplace AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_MARKET_PLACE_ERROR_ORDERS ), unicom_error AS ( SELECT u.*, CASE WHEN u.marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN u.warehouse_name = \'SAPL_EMIZA\' AND EXISTS (SELECT 1 FROM emiza WHERE emiza.\"Order ID\" = u.order_name AND emiza.warehouse = \'SAPL_EMIZA\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH\' AND EXISTS (SELECT 1 FROM wh WHERE wh.\"Order ID\" = u.order_name AND wh.warehouse = \'SAPL-WH\') THEN 1 WHEN u.warehouse_name = \'SAPL-SR\' AND EXISTS (SELECT 1 FROM sr WHERE sr.\"Order ID\" = u.order_name AND sr.warehouse = \'SAPL-SR\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH2\' AND EXISTS (SELECT 1 FROM wh2 WHERE wh2.\"Order ID\" = u.order_name AND wh2.warehouse = \'SAPL-WH2\') THEN 1 ELSE NULL END WHEN u.marketplace_mapped NOT IN (\'SHOPIFY\', \'OWN_STORE\', \'FRANCHISE_STORE\') THEN CASE WHEN EXISTS (SELECT 1 FROM marketplace WHERE marketplace.\"Order ID\" = u.order_name AND marketplace.warehouse = u.warehouse_name) THEN 1 ELSE NULL END ELSE NULL END AS ERROR FROM unicom u ), main_data AS ( SELECT ue.*, f.created_timestamp, f.picking_timestamp, f.picked_timestamp, f.packed_timestamp, f.rts_timestamp, f.manifested_timestamp, f.dispatched_timestamp1, f.shipped_timestamp, f.delivered_timestamp, f.cancelled_timestamp, f.\"created&dispatch\", f.\"pick&dispatch\", f.\"pack&dispatch\", f.LATEST_STATUS, f.LAST_UPDATED, cp.CP_orderplaced, cp.\"Pickup Date\", cp.CP_Delivery, cp.CP_STATUS FROM unicom_error ue LEFT JOIN forward f ON ue.shippingpackagecode = f.\"Shipping Package Code\" LEFT JOIN clickpost cp ON ue.awb = cp.awb ), over AS ( SELECT don, soic, facwarehouse, overrulestatus FROM snitch_db.maplemonk.gs_overrule ), mast1 AS ( SELECT md.*, ov.* FROM main_data md LEFT JOIN over ov ON md.saleorderitemcode = ov.soic ), new_status AS ( SELECT m1.*, CASE when overrulestatus = \'DISPATCHED\' THEN created_timestamp END AS dispatchedtimestamp1, COALESCE(dispatchedtimestamp1,\"UC_Dispatched\") AS dispatched_timestamp, coalesce (overrulestatus,UC_STATUS) as ITEM_STATUS, CASE WHEN ITEM_STATUS = \'CANCELLED\' THEN CASE WHEN dispatched_timestamp IS NULL THEN \'CANCELLED\' ELSE CASE WHEN dispatched_timestamp <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END END WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\',\'MANIFESTED\',\'PACKED\',\'READY_TO_SHIP\') THEN \'FUTURE DATE-COMPLETED\' WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS NOT IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\',\'MANIFESTED\',\'PACKED\',\'READY_TO_SHIP\') THEN \'FUTURE DATE-PENDING\' ELSE CASE WHEN ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURN_EXPECTED\',\'MANIFESTED\',\'PACKED\',\'READY_TO_SHIP\') THEN CASE WHEN packed_time <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END WHEN ITEM_STATUS IN (\'CREATED\', \'PICKING\', \'PICKED\', \'PICKING_FOR_INVOICING\', \'FULFILLABLE\') THEN \'BREACHED - PENDING FOR PROCESS\' WHEN ITEM_STATUS = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' ELSE \'BREACHED\' END END AS SLA_Status, CASE WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 0 THEN \'D0\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'D1\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 2 THEN \'D2\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 3 THEN \'D3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 3 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 5 THEN \'D>3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 5 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 7 THEN \'D>5\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 7 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 9 THEN \'D>7\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 9 THEN \'D>9\' END AS Ageing, case when dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' AND cp_status not in (\'Cancelled\',\'RTO-Delivered\') THEN \'Handover_Pending\' ELSE \'NA\' END AS handover_status, CASE WHEN dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) < 12 THEN \'<12H\' WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 12 AND 24 THEN \'1D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'2D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 2 AND 5 THEN \'5D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 5 AND 10 THEN \'10D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 10 AND 30 THEN \'30D\' ELSE \'30D+\' END ELSE \'NA\' END as handover_ageing, CASE WHEN item_status = \'CANCELLED\' AND dispatched_timestamp IS NULL THEN \'CANCELLED\' WHEN shippingpackagecode IS NOT NULL and shippingpackagecode not in (\'\') AND item_status = \'CANCELLED\' THEN \'RETURNED\' WHEN cp_status like \'RTO-Delivered\' then \'RTO_NOT_PROCESSED\' WHEN CP_STATUS like \'%RTO%\' THEN \'RTO-INTRANSIT\' WHEN cp_delivery IS NOT NULL AND cp_delivery NOT IN (\'\') THEN \'DELIVERED\' WHEN \"Pickup Date\" IS NOT NULL AND \"Pickup Date\" NOT IN (\'\') THEN \'IN-TRANSIT\' WHEN LOWER(item_status) LIKE \'%created%\' THEN \'ORDER_NOT_ACCEPTED\' WHEN LOWER(item_status) LIKE \'fulfillable%\' THEN \'ORDER_NOT_PROCESSED\' WHEN LOWER(item_status) LIKE \'%manifest%\' and \"Pickup Date\" is not null and \"Pickup Date\" not in (\'\') THEN \'MANIFEST_NOT_CLOSED\' WHEN \"Pickup Date\" IS NULL OR \"Pickup Date\" IN (\'\') THEN \'HANDOVER_PENDING\' END AS OMNI_FINAL_STATUS, CASE WHEN warehouse_name LIKE \'%JAYA%\' THEN CASE WHEN pincode IN (\'560068\',\'560076\',\'560078\',\'560029\',\'560085\',\'560004\',\'560034\',\'560062\',\'560061\',\'560027\',\'560095\',\'560070\',\'560050\',\'560026\',\'560030\',\'560011\',\'560041\',\'560025\',\'560018\',\'560002\',\'560053\',\'560019\',\'560069\',\'560007\',\'560028\',\'560108\',\'560111\') THEN \'PINCODE\' ELSE \'INV\' END ELSE \'INV\' END AS allocation_method FROM mast1 m1 ), final as ( SELECT a.*, cp.status as journey_status FROM new_status a left join snitch_db.maplemonk.cp_1 cp on a.awb = cp.awb_number ) select * from final WHERE (warehouse_name LIKE \'%EBO%\' or warehouse_name is null) AND marketplace_mapped like \'%SHOPIFY%\' AND order_timestamp::date >= \'2025-01-08\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            